from itertools import combinations
G=[(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)]
S=set(G)
# all 2x2 unit L's, mapped missing top-left ->2, missing top-right ->4, missing bottom-left ->3; bottom-right unknown
pieces=[]
for r in range(3):
 for c in range(5):
  block={(r+i,c+j) for i in (0,1) for j in (0,1)}
  if block<=S: pieces.append((1,block))
  for miss,color in [((0,0),2),((0,1),4),((1,0),3),((1,1),5)]:
   p=block-{(r+miss[0],c+miss[1])}
   if p<=S: pieces.append((color,p))
solutions=[]
def go(rem, chosen):
 if not rem:
  solutions.append(chosen); return
 x=min(rem)
 for col,p in pieces:
  if x in p and p<=rem:
   go(rem-p,chosen+[(col,tuple(sorted(p)))])
go(S,[])
print('n',len(solutions))
for sol in solutions[:20]:
 print([(c,[(r,c0) for r,c0 in p]) for c,p in sol])
